// PMP 刷题题库 · 自编情景题，非 PMI 真题
// d: 领域（人员/过程/敏捷/业务环境），a: 正确选项下标，why: 一句话解析
const BANK = [
{d:"业务环境",q:"某在建的客户数据平台项目已完成 60%，此时监管部门发布新的数据保护法规，要求所有用户数据的存储和处理方式作出调整。项目经理首先应该怎么做？",options:["立即按新法规要求修改项目范围，让团队着手调整","通知团队暂停手头工作，等待法规实施细则出台","先评估法规变化对项目范围、进度和成本的影响，并通过变更控制流程处理","等法规正式生效后再决定是否调整项目"],a:2,why:"法规变化先评估影响、再走变更流程，不能直接动手改，也不能干等。"},
{d:"业务环境",q:"一个新业务系统上线三个月后，业务部门反馈实际收益明显低于业务论证中的预期。项目经理最恰当的做法是？",options:["项目已按计划交付，宣布项目成功并关闭","与项目发起人一起复核收益实现计划，分析收益差距的原因并制定改进措施","立即立项一个新项目来弥补收益缺口","将收益问题全部移交给运营部门，不再跟进"],a:1,why:"收益没达标要复核收益实现计划、找原因、定改进措施，而不是宣布成功或甩手。"},
{d:"业务环境",q:"公司因市场战略调整，重新排定了各项目的优先级，你负责的项目优先级被下调，资源可能被抽走。项目经理首先应该怎么做？",options:["不受影响，继续按原计划全速推进","自行缩减项目范围以适应可能减少的资源","直接解散项目团队，等待进一步通知","与项目发起人确认战略调整对项目目标和优先级的影响，并据此调整项目安排"],a:3,why:"战略变了先和发起人确认对项目目标的影响，再调整安排，不能自作主张。"},
{d:"业务环境",q:"项目关键部件的唯一供应商所在地区出台了新的出口管制政策，交付时间存在很大的不确定性。项目经理最恰当的做法是？",options:["将该风险记入风险登记册，评估其对进度和成本的影响，并制定应对策略（如寻找备选供应商）","立即终止与该供应商的合同，改用本地供应商","这是政策层面的问题，项目层面无法应对，暂不处理","直接要求客户同意延长项目工期"],a:0,why:"识别到的风险先登记、评估影响、定应对策略，而不是立即毁约或放任。"},
{d:"业务环境",q:"由于市场环境发生重大变化，发起人决定提前终止一个已完成 70% 的产品开发项目。项目经理首先应该怎么做？",options:["立即解散团队，停止一切工作","按收尾流程完成项目收尾，总结经验教训，并妥善移交已完成的可交付成果","说服发起人让团队把剩余 30% 做完再关闭","封存项目文档，不再做任何移交"],a:1,why:"提前终止也要走正式收尾：总结教训、移交成果，不能一散了之。"},
{d:"人员",q:"你负责一个跨三地协作的系统重构项目，下周要给客户演示核心模块，但进度已比计划晚了两周。两名骨干成员因为技术路线吵了起来：一位在项目群里公开质疑另一位的方案，另一位则开始私下按自己的版本推进，代码合并冲突越来越多。职能经理建议你把其中一人调离团队，先保住演示。你最先应该做什么？",options:["按职能经理的建议把其中一人调离，避免演示前再起冲突","立即召集全员开会，让团队投票选出技术路线，少数服从多数","分别私下找两人了解各自的诉求和顾虑，再引导他们围绕演示目标商量出双方都能接受的解决办法","把冲突升级给项目发起人，请发起人裁定技术路线"],a:2,why:"冲突先私下了解诉求、引导围绕目标协商；调离、投票、升级都是跳过自己的职责。"},
{d:"过程",q:"你负责的系统升级项目已完成约 65%，CPI 为 0.88，SPI 为 0.95。本周评审会上，客户高管当场要求加一个报表功能，说下月审计要用，暗示不加可能影响验收；团队骨干说这个功能顺手就能做，不用走流程；坐在现场的项目发起人也点头表示支持。你最恰当的做法是？",options:["既然发起人已点头、团队也说能做，就直接安排开发，事后再补变更记录","先让团队评估新增功能对范围、进度和成本的影响，再走变更控制流程审批，获批后再调整基准","因为成本已经超支，直接拒绝这个新增需求，坚持按原范围交付","请客户高管直接向发起人施压，由发起人拍板要不要加"],a:1,why:"哪怕发起人点头，也得先评估影响、走变更流程、获批后再调基准；事后补记录等于先斩后奏。"},
{d:"敏捷",q:"你带的敏捷团队正在做第 3 个 Sprint，本 Sprint 目标是支付链路稳定上线，还剩 3 天。产品负责人收到大客户投诉，要求在本 Sprint 内加一个退款功能，并建议把已排入本 Sprint 的一个次要优化项换出来；开发团队里有人反对，认为会打乱节奏，也有人觉得客户最大应该接。作为服务型领导的项目经理，你最恰当的做法是？",options:["直接接受新需求并把 Sprint 延长两天，保证新旧工作都做完","告诉产品负责人只能等下个 Sprint 规划会再排，本 Sprint 内不讨论","让开发团队内部投票决定接不接，项目经理不干预","组织产品负责人和开发团队一起评估新需求对 Sprint 目标和已承诺工作的影响，共同决定是否置换、如何调整"],a:3,why:"PO 和团队一起评估对 Sprint 目标的影响、共同决定是否置换；延长 Sprint 破坏节奏，投票则交出了 PO 的优先级权。"},
{d:"业务环境",q:"你负责的海外业务系统原定下月上线抢市场，但当地刚出台新规，要求用户数据必须存储在境内；现有合同约定供应商在境外数据中心统一托管，改成本地机房要加价且至少需要 6 周。法务提醒违规可能面临罚款甚至停服，市场部门催着按原定日期上线，供应商则说可以先签补充协议慢慢迁移。你最恰当的做法是？",options:["先与法务和发起人一起评估合规风险以及切换带来的成本和时间影响，更新风险登记册，并通过变更流程决定应对方案","立即终止与现有供应商的合同，改找本地供应商，保证合规上线","按原计划上线，等监管真正执法时再迁移","接受供应商的补充协议提议，先上线再说，迁移的事以后内部再定"],a:0,why:"合规风险先评估成本和时间影响、更新风险登记册、走变更流程；毁约、违规上线、先上再说都是拿罚款和停服赌。"},
{d:"混合",q:"你负责的制造企业数字化项目进入上线审批关键周，负责合规签字的关键干系人连续两周缺席评审会，邮件只回“在忙”；团队的测试报告和上线材料都已准备好，但没有他的签字就不能切换系统。有人建议你直接找他的上级施压，有人建议不等签字先切换抢窗口，项目发起人也在问你为什么卡在这里。你最恰当的做法是？",options:["直接越级找该干系人的上级，要求对方限期签字","不等签字先按计划切换系统，事后再补签","把上线日期无限期推后，等该干系人自己有空再说","先分析该干系人缺席的原因以及他真正关心的信息和参与方式，调整沟通方式后再推动签字"],a:3,why:"签字人缺席先分析原因、换种沟通方式再推动；越级施压、先斩后奏、无限期推后都不对。"},
{d:"人员",q:"你是某金融系统升级项目的项目经理，团队分在北京和成都两地。执行中期，一名核心开发连续两周在站会上几乎不说话，交付也开始延迟。私下聊天时他说，自己的技术判断总被架构师否决，干着没劲。你最先应该怎么做？",options:["在下次团队会议上公开指出他的表现问题，让大家一起帮他找原因","直接把他调离当前关键模块，换一个积极性更高的人顶上","私下和他认真谈一次，了解他的诉求和受阻点，肯定他的贡献，并协商调整分工或让他更多参与技术决策","找架构师谈话，要求他以后必须采纳这名开发的意见"],a:2,why:"人出问题先私下谈，了解诉求、肯定贡献、协商调整；公开点名是羞辱，调离是逃避，命令架构师是越权。"},
{d:"过程",q:"你的项目已完成约 40%，挣值数据如下：计划价值 200 万，挣值 160 万，实际成本 180 万。此时客户要求提前一个月交付，团队有人提议压缩测试周期来抢时间。你应该怎么做？",options:["先分析进度与成本偏差的原因，评估赶工和快速跟进等方案对成本、质量的影响，然后提交变更请求","答应客户要求，直接压缩测试周期赶进度","拒绝客户的要求，坚持按原计划交付","增加人手、让团队加班赶工，但不走变更流程"],a:0,why:"进度和成本双双落后时，先分析偏差原因、评估赶工和快速跟进的影响，再走变更；压缩测试是拿质量换时间。"},
{d:"敏捷",q:"Sprint 进行到一半，团队发现某个用户故事的验收标准存在歧义，而产品负责人正在出差、暂时联系不上。开发人员已经按自己的理解做了两天。你最恰当的做法是？",options:["让开发继续按自己的理解做完，等产品负责人回来验收时再说","召开全体会议投票决定这条故事的验收标准","延长当前 Sprint，等产品负责人回来再澄清","先暂停这条故事，让团队转向其他已经澄清的工作，同时通过约定渠道请产品负责人尽快澄清"],a:3,why:"验收标准有歧义不能靠猜，先暂停这条、做其他已澄清的工作，同时请 PO 尽快澄清；投票定标准是越权。"},
{d:"业务环境",q:"公司战略调整后要求所有新项目必须通过 ESG 评估。你的项目已执行 60%，发起人要求你补一份 ESG 合规报告，但不增加预算和工期。你应该怎么做？",options:["直接拒绝，理由是项目已经过半、无法再加东西","评估合规要求对范围、成本、进度的影响，更新相关文件，并通过变更流程决定方案","先自己垫资找外部机构出报告，流程以后再补","把 ESG 报告当作收尾文档，项目结束后再补"],a:1,why:"战略合规要求来了，先评估对范围、成本、进度的影响再走变更；拒绝无视战略，垫资先做是先斩后奏。"},
{d:"混合",q:"一位关键干系人（业务部门负责人）在启动会上很支持项目，但执行中连续三次评审会都不参加。团队按原有假设推进，后来他说方向偏了。你最先应该怎么做？",options:["在项目群里公开提醒他，要求以后必须参会","把已做的工作推倒重来，按他最新的意见改","请发起人出面施压，要求他参加后续评审","与他单独沟通，了解他缺席的原因和期望的参与方式，并相应调整干系人参与计划"],a:3,why:"干系人缺席先单独沟通原因、调整参与方式；公开提醒、推倒重来、找发起人施压都只会把关系搞僵。"},];

// ---- 新增：人员 ----
BANK.push(
{d:"人员",q:"项目进入执行阶段，两名资深成员对架构选型各执己见，争论已经影响到迭代进度。作为项目经理，你最先应该做什么？",options:["直接拍板选一个方案，让团队立刻执行","把两人分到不同模块，眼不见为净","分别了解双方的技术依据和顾虑，引导他们用演示目标和验收标准来评判方案","把选型问题上报给发起人裁决"],a:2,why:"先了解依据、再用共同目标引导协商；拍板、分流、上报都跳过了引导冲突的职责。"},
{d:"人员",q:"团队新加入一名外包开发，连续两次交付的代码都没有通过评审，老成员开始在群里公开抱怨。你最恰当的做法是？",options:["在群里提醒老成员注意言辞，同时私下了解新成员的困难并安排结对帮带","直接把新成员退回外包公司","让新成员独自加班补齐质量差距","公开批评老成员破坏团队氛围"],a:0,why:"两边都要处理：公开抱怨要制止，新成员要私下了解困难并给支持；退回、加班、单边批评都不对。"},
{d:"人员",q:"Sprint 回顾会上，团队成员普遍反映需求经常中途变化，导致返工严重。作为服务型领导，你首先应该推动什么？",options:["要求产品负责人以后不许再改需求","把回顾会的结论记下来，但不采取任何行动","和产品负责人一起梳理需求变更的来源和流程，约定变更进入待办的规则","延长 Sprint 长度，给返工留出缓冲"],a:2,why:"回顾会的价值在改进：和 PO 一起定变更规则；禁改需求不现实，只记录不行动等于白开。"},
{d:"人员",q:"项目关键岗位的骨干突然提出离职，离职期只有两周，而他掌握的核心模块文档很少。你最先应该做什么？",options:["立刻启动招聘，争取两周内找到替代者","和他协商知识交接计划，优先把核心模块的文档和关键决策补齐","把他的工作平均分给其余成员","请发起人出面挽留，不惜加薪"],a:1,why:"离职期最宝贵的是知识交接，先把核心模块的文档和决策补齐；招聘和分工都赶不上两周窗口。"},
{d:"人员",q:"虚拟团队分布在三个时区，成员反映会议总在有人深夜的时间开，参与度越来越低。你最恰当的做法是？",options:["固定一个对多数人友好的时间，少数人克服一下","轮换会议时间，并用异步文档和录像保证没参会的人也能跟上","取消所有同步会议，全部改异步","要求所有成员统一调整作息"],a:1,why:"跨时区团队要轮换时间 + 异步兜底；固定时间牺牲少数人，取消会议则失去同步价值。"},
{d:"人员",q:"一名表现一直很好的成员最近连续迟到、交付质量下滑。私下沟通后得知他家里出了变故。你最恰当的做法是？",options:["按绩效制度直接启动警告流程","暂时调整他的工作量和关键任务，表达支持，并约定复查时间","把他的任务全部转交他人，让他彻底休息","在团队会上公开说明情况，争取大家谅解"],a:1,why:"了解原因后调整工作量、给支持、约定复查；直接警告太冷，全部转交是剥夺，公开家事侵犯隐私。"},
{d:"人员",q:"团队采用敏捷后，老板仍要求每周提交详细的个人工时报表，成员觉得被监视、积极性下降。你应该怎么做？",options:["照做，老板的要求必须执行","私下劝成员忍一忍","和老板沟通，用团队交付成果和迭代演示来替代个人工时报表","让成员轮流编报表，糊弄过去"],a:2,why:"用交付成果替代过程监控，和上级协商 reporting 方式；照做打击士气，糊弄是诚信问题。"},
{d:"人员",q:"项目中期，一名成员坚持认为某个技术方案有重大隐患，但多数人觉得他小题大做。项目经理最恰当的做法是？",options:["少数服从多数，继续推进","把他的担忧记入风险登记册并组织一次技术评估，确认隐患是否真实","让他自己去验证，验证出来再说","为了团结，私下请他不要再提"],a:1,why:"隐患担忧要登记并组织评估，用证据说话；投票压制、放任自证、压下去都可能埋雷。"},
{d:"人员",q:"跨部门项目中，业务方派来的代表经常不参加例会，需求确认一拖再拖。你最先应该做什么？",options:["直接找业务方领导投诉","了解对方不参会的原因，协商他能接受的参与方式（如短会、异步确认）","绕过他，直接按团队理解推进","把项目延期，责任记在他头上"],a:1,why:"参与度问题先了解原因、协商参与方式；投诉、绕过、甩锅都会恶化合作。"},
{d:"人员",q:"团队里两位成员因为代码风格问题在评审中吵了起来，评审会变成了互相挑刺。你作为主持者应该怎么做？",options:["宣布以后评审只看功能，不看风格","当场裁定一种风格，所有人遵守","引导团队把风格争议落到统一规范上，会后形成检查清单，评审回归事实","取消代码评审，改成结对编程"],a:2,why:"把个人争议转为团队规范和检查清单；只看功能放弃质量，单方面裁定难服众，取消评审是因噎废食。"},
{d:"人员",q:"项目经理发现团队成员对项目目标理解不一致：有人认为是保上线时间，有人认为是保质量。你首先应该做什么？",options:["各自按理解推进，年底看结果","召集团队重申项目目标和成功标准，并确认优先级排序","写一份长篇项目愿景文档发给大家","请发起人来给团队训话"],a:1,why:"目标不一致先对齐：重申目标和成功标准并确认优先级；放任、发文档、训话都解决不了理解分歧。"},
{d:"人员",q:"敏捷团队的开发人员抱怨产品负责人经常在 Sprint 中途插单，导致承诺无法兑现。你最恰当的做法是？",options:["告诉开发人员客户最大，忍一忍","和产品负责人协商：中途插单走紧急变更评估，确需插入则置换出等量工作","禁止产品负责人和开发人员直接沟通","把 Sprint 改成看板模式，取消承诺"],a:1,why:"插单要走评估 + 等量置换，保护 Sprint 承诺；忍一忍透支团队，禁沟通破坏协作，改模式是逃避问题。"},
);

